def cost_ratio(steps_messaging, steps_reasoning, threshold=0.9):
    # steps_*: 达到 threshold 成功率所需训练步数；None 表示未学会
    if steps_reasoning is None:
        return None                     # 学不会，比值无定义
    return steps_reasoning / max(steps_messaging, 1)

ratio = cost_ratio(1000, 2500)
print(ratio, ratio >= 2)               # 2.5 True

import numpy as np

def pairwise_agreement(model_scores, env_scores):
    n, c, d = len(model_scores), 0, 0
    for i in range(n):
        for j in range(i + 1, n):
            m = np.sign(model_scores[i] - model_scores[j])
            e = np.sign(env_scores[i] - env_scores[j])
            if m == e:
                c += 1
            elif m != 0:
                d += 1
    return (c - d) / (n * (n - 1) / 2)

tau = pairwise_agreement(model_scores, env_scores)

import torch, torch.nn as nn

class LatentWM(nn.Module):
    def __init__(self, dim, act_dim):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(dim + act_dim, 256), nn.ReLU(), nn.Linear(256, dim))

    def forward(self, z, a):
        return self.net(torch.cat([z, a], dim=-1))

def pred_loss(model, z_t, a_nom, z_next):
    return ((model(z_t, a_nom) - z_next) ** 2).mean()

import torch, torch.nn as nn

class InvDyn(nn.Module):
    def __init__(self, dim, act_dim):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(2 * dim, 256), nn.ReLU(), nn.Linear(256, act_dim))

    def forward(self, z_t, z_next):
        return self.net(torch.cat([z_t, z_next], dim=-1))

def inv_loss(model, z_t, z_next, a_real):
    return ((model(z_t, z_next) - a_real) ** 2).mean()

def safety_gap(model, z_t, z_next, a_nom):
    return (a_nom - model(z_t, z_next)).norm(dim=-1)
